#define NET_LOG_LEVEL CONFIG_NET_IPV6_LOG_LEVEL
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(net_ipv6_test, NET_LOG_LEVEL);

/* Define a memory slab for TX packets */
NET_PKT_TX_SLAB_DEFINE(tx, 10);
NET_PKT_RX_SLAB_DEFINE(rx, 10);

static struct net_if *test_iface;
static struct net_linkaddr ll_addr;

static void net_test_setup(void)
{
    /* Initialize network stack */
    net_mgmt_init();

    /* Get a test interface */
    test_iface = net_if_get_default();
    zassert_not_null(test_iface, "No default network interface found");

    /* Set up a dummy link address */
    ll_addr.type = NET_LINK_ETHERNET;
    ll_addr.len = sizeof(struct net_eth_addr);
    net_linkaddr_set_mac(&ll_addr, (uint8_t[]){0x00, 0x00, 0x00, 0x00, 0x00, 0x01});
    net_if_set_link_addr(test_iface, &ll_addr);

    /* Bring interface up */
    net_if_up(test_iface);
    net_if_carrier_on(test_iface);

    /* Add a dummy IPv6 address */
    struct in6_addr addr;
    net_addr_parse_ipv6("2001:db8::1", &addr);
    net_if_ipv6_addr_add(test_iface, &addr, NET_ADDR_MANUAL, 0);

    /* Clear any pending packets from previous tests */
    struct net_pkt *pkt;
    while ((pkt = net_pkt_get_tx(test_iface, K_NO_WAIT)) != NULL) {
        net_pkt_unref(pkt);
    }
    while ((pkt = net_pkt_get_rx(test_iface, K_NO_WAIT)) != NULL) {
        net_pkt_unref(pkt);
    }
}

static void net_test_teardown(void)
{
    /* Bring interface down */
    net_if_carrier_off(test_iface);
    net_if_down(test_iface);

    /* Remove IPv6 address */
    struct in6_addr addr;
    net_addr_parse_ipv6("2001:db8::1", &addr);
    net_if_ipv6_addr_rm(test_iface, &addr);

    /* Ensure all packets are freed */
    zassert_equal(k_mem_slab_num_free_get(tx), 10, "TX slab not empty after test suite");
    zassert_equal(k_mem_slab_num_free_get(rx), 10, "RX slab not empty after test suite");
}

/* Helper to simulate sending a packet and checking if it's freed */
static int simulate_send_nd_pkt(struct net_if *iface, struct net_pkt *pkt,
                                 const struct in6_addr *dst_addr,
                                 const struct in6_addr *src_addr,
                                 enum net_ipv6_nd_msg_type type,
                                 const void *options, size_t options_len,
                                 bool fail_send)
{
    ARG_UNUSED(iface);
    ARG_UNUSED(dst_addr);
    ARG_UNUSED(src_addr);
    ARG_UNUSED(type);
    ARG_UNUSED(options);
    ARG_UNUSED(options_len);

    if (fail_send) {
        return -EIO; /* Simulate send failure */
    }

    /* In a real scenario, the packet would be consumed by the stack.
     * For this test, we just unref it to simulate consumption.
     */
    net_pkt_unref(pkt);
    return 0;
}

