/* This is the function that needs fixing */
static void net_ipv6_test_send_neighbor_discovery(void)
{
    struct net_if *iface = test_iface;
    struct net_pkt *pkt = NULL;
    int ret;
    int avail_pkt_count = k_mem_slab_num_free_get(tx);
    struct in6_addr src_addr;
    struct in6_addr dst_addr;

    net_addr_parse_ipv6("2001:db8::2", &src_addr);
    net_addr_parse_ipv6("ff02::1", &dst_addr); /* All-nodes multicast */

    /* Test case 1: Successful send */
    pkt = net_pkt_get_tx(iface, K_FOREVER);
    zassert_not_null(pkt, "Cannot get TX packet for successful send");

    /* Simulate filling the packet with ND data */
    net_pkt_set_family(pkt, AF_INET6);
    net_pkt_set_iface(pkt, iface);
    net_pkt_set_priority(pkt, NET_PRIORITY_ND);
    net_pkt_set_ipv6_hop_limit(pkt, 255);

    /* Simulate calling a send function that consumes the packet */
    ret = simulate_send_nd_pkt(iface, pkt, &dst_addr, &src_addr,
                               NET_IPV6_ND_ROUTER_SOLICIT, NULL, 0, false);
    zassert_equal(ret, 0, "Successful send failed unexpectedly");
    pkt = NULL; /* Packet is consumed/freed by simulate_send_nd_pkt */

    /* Test case 2: Failed send - this is where the leak likely occurs */
    pkt = net_pkt_get_tx(iface, K_FOREVER);
    zassert_not_null(pkt, "Cannot get TX packet for failed send");

    /* Simulate filling the packet with ND data */
    net_pkt_set_family(pkt, AF_INET6);
    net_pkt_set_iface(pkt, iface);
    net_pkt_set_priority(pkt, NET_PRIORITY_ND);
    net_pkt_set_ipv6_hop_limit(pkt, 255);

    /* Simulate calling a send function that fails and does NOT consume the packet */
    ret = simulate_send_nd_pkt(iface, pkt, &dst_addr, &src_addr,
                               NET_IPV6_ND_ROUTER_SOLICIT, NULL, 0, true);
    zassert_not_equal(ret, 0, "Failed send succeeded unexpectedly");

    /* FIX: If the send fails, the packet must be unreferenced by the caller. */
    if (pkt) { /* Check if pkt is still valid (not consumed by simulate_send_nd_pkt) */
        net_pkt_unref(pkt);
        pkt = NULL;
    }

    /* Ensure all packets are freed */
    /* This assertion is at line 956 in the original file, based on the error log. */
    zassert_equal(k_mem_slab_num_free_get(tx), avail_pkt_count,
                  "Packet not freed after test");
}

ZTEST_SUITE(net_ipv6_test, NULL, NULL, net_test_setup, net_test_teardown, NULL);

ZTEST_USER(net_ipv6_test, test_prefix_timeout_long);
