ZTEST_USER(net_ipv6_test, test_rs_after_iface_up);
ZTEST_USER(net_ipv6_test, test_rs_after_iface_up_carrier_delayed);
ZTEST_USER(net_ipv6_test, test_rs_ra_message);
ZTEST_USER(net_ipv6_test, net_ipv6_test_send_neighbor_discovery);
